<?php
require_once dirname(__DIR__).'/includes/bootstrap.php';require_module('approvals');$id=(int)($_GET['id']??0);$s=db()->prepare("SELECT a.*,COALESCE(b.budget_code,e.expense_code) request_code,COALESCE(b.description,e.description) description,COALESCE(b.department_id,e.department_id) department_id FROM approvals a LEFT JOIN budgets b ON a.request_type='budget' AND b.id=a.request_id LEFT JOIN expenses e ON a.request_type='expense' AND e.id=a.request_id WHERE a.id=?");$s->execute([$id]);$a=$s->fetch();if(!$a){flash('danger','Approval request not found.');redirect('approvals/index.php');}if(!is_admin() && has_role(['Sales Manager','Marketing Manager']) && (int)$a['department_id']!==(int)current_user()['department_id']){http_response_code(403);require ROOT_PATH.'/includes/access_denied.php';exit;}$h=db()->prepare("SELECT h.*,CONCAT(u.first_name,' ',u.last_name) actor,r.name role_name FROM approval_history h JOIN users u ON u.id=h.action_by JOIN roles r ON r.id=u.role_id WHERE h.approval_id=? ORDER BY h.id");$h->execute([$id]);$hist=$h->fetchAll();$pageTitle='Approval History';$activeMenu='approvals';require ROOT_PATH.'/includes/header.php';?>
<div class="page-head"><div><h1>Approval History</h1><p><?=e($a['request_code'])?> · <?=e($a['description'])?></p></div><a class="btn btn-light border" href="<?=e(url('approvals/index.php'))?>">Back to Queue</a></div><div class="row"><div class="col-lg-8"><div class="card-panel"><div class="card-head"><h2 class="section-title">Workflow Timeline</h2><?=status_badge($a['status'])?></div><div class="card-body"><?php foreach($hist as $i=>$x):$done=in_array($x['action'],['Approved','Submitted','Resubmitted'],true);$rej=$x['action']==='Rejected';?><div class="approval-step <?=$rej?'rejected':($done?'done':'')?>"><div><div class="dot"><i class="fa-solid <?=$rej?'fa-xmark':'fa-check'?>"></i></div><?php if($i<count($hist)-1):?><div class="line"></div><?php endif;?></div><div class="pb-4"><strong><?=e($x['action'])?> · <?=e(ucwords(str_replace('_',' ',$x['stage'])))?></strong><div class="small text-secondary"><?=e($x['actor'])?> (<?=e($x['role_name'])?>) · <?=e(date('M d, Y h:i A',strtotime($x['created_at'])))?></div><div class="mt-1"><?=e($x['remarks'])?></div></div></div><?php endforeach;?></div></div></div></div><?php require ROOT_PATH.'/includes/footer.php';?>
